{
  "name": "policy-schedule-data-pipeline",
  "build": {
    "dockerfile": "Dockerfile",
    "context": ".."
  },
  "features": {
    "ghcr.io/devcontainers/features/common-utils:2": {
      "installZsh": "true",
      "configureZshAsDefaultShell": "true",
      "username": "vscode",
      "upgradePackages": "true"
    },
    "ghcr.io/devcontainers/features/github-cli:1": {},
    // Azure CLI + azure-devops extension: `az repos pr`, `az pipelines`,
    // `az boards` against dev.azure.com/OMIDataOffice (defaults set in
    // post-create.sh). Auth via AZURE_DEVOPS_EXT_PAT below or `az login`.
    "ghcr.io/devcontainers/features/azure-cli:1": {
      "extensions": "azure-devops"
    }
  },
  // kedro-viz serves the interactive pipeline graph on 4141 (scripts: `kedro viz`).
  "forwardPorts": [4141],
  "portsAttributes": {
    "4141": {
      "label": "kedro-viz",
      "onAutoForward": "openBrowserOnce"
    }
  },
  "remoteUser": "vscode",
  "updateRemoteUserUID": true,
  "workspaceFolder": "/workspaces/${localWorkspaceFolderBasename}",
  "mounts": [
    // Shared shell config (zshrc / starship / tmux) — single source of truth
    // from the host's ~/env checkout (https://github.com/neeland/env).
    "source=${localEnv:HOME}/env,target=/home/vscode/env,type=bind,consistency=cached,readonly",
    "source=${localEnv:HOME}/.ssh,target=/home/vscode/.ssh,type=bind,consistency=cached",
    // AWS creds for the S3 artifact root (PSDP_DATA_ROOT) + viz deploys: the
    // host's aws-azure-login STS tokens (refresh via scripts/az_login.sh on
    // the host; the dir is auto-created if absent).
    "source=${localEnv:HOME}/.aws,target=/home/vscode/.aws,type=bind,consistency=cached"
    // NOTE: do NOT bind-mount ~/.gitconfig. A single-file bind mount is an
    // immovable mount point, so VS Code's `git config --global
    // credential.helper` (atomic temp-file + rename) fails with "Device or
    // resource busy" and the container never finishes starting. Dev Containers
    // already copies the host gitconfig in as a writable file
    // (`dev.containers.copyGitConfig`, default true).
  ],
  "remoteEnv": {
    "PYTHONDONTWRITEBYTECODE": "1",
    "PATH": "${containerEnv:PATH}:/home/vscode/.local/bin",
    "UV_LINK_MODE": "copy",
    // Oracle Instant Client baked into the image (see Dockerfile). The pipeline
    // reads this as oracle.lib_dir for thick-mode init; ldconfig already knows
    // the path, so LD_LIBRARY_PATH is not required.
    "ORACLE_CLIENT_LIB": "/opt/oracle/instantclient",
    // Live TIA/Oracle pull password. The `full` run reads $TIA_PASSWORD from
    // the shell (conf/base/parameters.yml -> oracle.password). Passed through
    // from your HOST env if set there; otherwise put it in the repo's .env
    // (loaded by launch.json / python-dotenv). Never committed.
    "TIA_PASSWORD": "${localEnv:TIA_PASSWORD}",
    // Azure DevOps PAT for non-interactive az devops/repos/pipelines/boards
    // calls. Passed through from the HOST env if set; never committed.
    "AZURE_DEVOPS_EXT_PAT": "${localEnv:AZURE_DEVOPS_EXT_PAT}"
  },
  "customizations": {
    "vscode": {
      "extensions": [
        "ms-python.python",
        "ms-python.vscode-pylance",
        "ms-toolsai.jupyter",
        "kedro.Kedro",
        "charliermarsh.ruff",
        "redhat.vscode-yaml",
        "tamasfe.even-better-toml",
        "Oracle.oracledevtools",
        "GrapeCity.gc-excelviewer",
        "bierner.markdown-mermaid",
        "ms-toolsai.datawrangler",
        "Anthropic.claude-code",
        "ms-vsts.team"
      ],
      "settings": {
        "terminal.integrated.defaultProfile.linux": "zsh",
        "editor.formatOnSave": true,
        "python.defaultInterpreterPath": "${workspaceFolder}/.venv/bin/python",
        "python.analysis.typeCheckingMode": "basic",
        "python.testing.pytestEnabled": true,
        "python.testing.pytestArgs": ["tests"]
      }
    }
  },
  "postCreateCommand": "bash .devcontainer/post-create.sh"
}

